-- Transactional integration test, usable with psql -v ON_ERROR_STOP=1.
begin;
create function pg_temp.check_game(p_condition boolean,p_message text) returns void language plpgsql as $$begin if p_condition is distinct from true then raise exception 'game_test_failed: %',p_message; end if; end$$;
create function pg_temp.reject_game(p_sql text,p_expected text) returns void language plpgsql as $$
declare got text;
begin begin execute p_sql; exception when others then got:=sqlerrm; end;
 if got is null or position(p_expected in got)=0 then raise exception 'game_test_failed: expected %, got %',p_expected,got; end if;
end$$;
insert into auth.users(id,email) values('f1000000-0000-4000-8000-000000000001','game-editor@example.invalid'),('f1000000-0000-4000-8000-000000000002','game-mobile@example.invalid'),('f1000000-0000-4000-8000-000000000003','game-other@example.invalid');
insert into public.profiles(user_id,display_name) select id,'Game test' from auth.users where id::text like 'f1000000-%' on conflict(user_id) do nothing;
insert into public.editor_access(email,user_id,role,active) values('game-editor@example.invalid','f1000000-0000-4000-8000-000000000001','admin',true);
insert into public.species(id,catalog_code,scientific_name,common_name,status) values('f2000000-0000-4000-8000-000000000001','game-test','Testus species','Nombre secreto','active');
insert into public.catalog_sources(id,code,name,license,use_policy) values('f3000000-0000-4000-8000-000000000001','game-test','Test','CC BY 4.0','redistributable'),('f3000000-0000-4000-8000-000000000002','game-review-only','Review only','NC','review_only');
create temporary table game_ids(k text primary key,id uuid);
grant all on game_ids to authenticated;
do $$begin execute format('grant usage on schema %I to authenticated',pg_my_temp_schema()::regnamespace::text); end$$;
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select pg_temp.check_game(not has_table_privilege('authenticated','public.species_game_clues','insert'),'no direct editorial write');
select pg_temp.check_game(not has_table_privilege('anon','public.species_game_clues','select'),'no anonymous editorial read');
select pg_temp.check_game(not has_function_privilege('anon','public.sync_enriched_game_records(jsonb)','execute'),'no anonymous progress RPC');
select pg_temp.reject_game($$select public.submit_content_change('game_clue',null,'f2000000-0000-4000-8000-000000000001','upsert','{"kind":"habitat","sort_order":1,"body":"Habita cerca de cursos de agua.","source_id":"f3000000-0000-4000-8000-000000000002"}')$$,'redistributable_source_required');
select pg_temp.reject_game($$select public.submit_content_change('game_clue',null,'f2000000-0000-4000-8000-000000000001','upsert','{"kind":"habitat","sort_order":1,"body":"El nombre secreto habita en campos.","source_id":"f3000000-0000-4000-8000-000000000001"}')$$,'clue_reveals_answer');
insert into game_ids select 'first',public.submit_content_change('game_clue',null,'f2000000-0000-4000-8000-000000000001','upsert','{"kind":"habitat","sort_order":1,"body":"Habita cerca de cursos de agua.","source_id":"f3000000-0000-4000-8000-000000000001"}');
select pg_temp.check_game((select count(*) from public.species_game_clues where species_id='f2000000-0000-4000-8000-000000000001')=0,'pending clues are not published');
select pg_temp.reject_game($$select public.review_content_change((select id from game_ids where k='first'),true,false)$$,'self_validation_confirmation_required');
insert into game_ids select 'clue',public.review_content_change((select id from game_ids where k='first'),true,true);
select pg_temp.check_game((select count(*) from public.species_game_clues where species_id='f2000000-0000-4000-8000-000000000001')=1,'approved clue visible');
insert into game_ids select 'edit',public.submit_content_change('game_clue',(select id from game_ids where k='clue'),'f2000000-0000-4000-8000-000000000001','upsert','{"kind":"habitat","sort_order":1,"body":"Habita entre pastizales abiertos.","source_id":"f3000000-0000-4000-8000-000000000001"}');
insert into game_ids select 'stale',public.submit_content_change('game_clue',(select id from game_ids where k='clue'),'f2000000-0000-4000-8000-000000000001','archive','{}');
select public.review_content_change((select id from game_ids where k='edit'),true,true);
select pg_temp.reject_game($$select public.review_content_change((select id from game_ids where k='stale'),true,true)$$,'clue_change_conflict');
select pg_temp.check_game((select before_values->>'body' from public.content_changes where id=(select id from game_ids where k='edit'))='Habita cerca de cursos de agua.','previous clue preserved in audit');
insert into game_ids select 'rejected',public.submit_content_change('game_clue',null,'f2000000-0000-4000-8000-000000000001','upsert','{"kind":"diet","sort_order":2,"body":"Su alimentación incluye semillas.","source_id":"f3000000-0000-4000-8000-000000000001"}');
select public.review_content_change((select id from game_ids where k='rejected'),false,true);
select pg_temp.check_game(not exists(select 1 from public.species_game_clues where species_id='f2000000-0000-4000-8000-000000000001' and kind='diet'),'rejection changes no clues');
insert into game_ids select 'archive',public.submit_content_change('game_clue',(select id from game_ids where k='clue'),'f2000000-0000-4000-8000-000000000001','archive','{}');
select public.review_content_change((select id from game_ids where k='archive'),true,true);
select pg_temp.check_game((select active from public.species_game_clues where id=(select id from game_ids where k='clue'))=false,'archive retains clue');
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select pg_temp.check_game((select count(*) from public.species_game_clues)=0,'mobile cannot read editorial clues');
select pg_temp.reject_game($$select public.submit_content_change('game_clue',null,'f2000000-0000-4000-8000-000000000001','archive','{}')$$,'editor_access_required');
select public.sync_enriched_game_records('[{"mode":"guess_search","scope":"animals_all:hard","best_score":400,"best_time_ms":0,"fewest_moves":0,"played_at":1000,"updated_at":1000},{"mode":"jigsaw","scope":"birds:hard:3","best_score":0,"best_time_ms":6000,"fewest_moves":24,"played_at":1000,"updated_at":1000}]');
select public.sync_enriched_game_records('[{"mode":"guess_search","scope":"animals_all:hard","best_score":100,"best_time_ms":0,"fewest_moves":0,"played_at":2000,"updated_at":2000},{"mode":"jigsaw","scope":"birds:hard:3","best_score":0,"best_time_ms":8000,"fewest_moves":20,"played_at":2000,"updated_at":2000}]');
select pg_temp.check_game((select best_score from public.mobile_enriched_game_records where mode='guess_search')=400,'score keeps maximum');
select pg_temp.check_game((select best_time_ms=6000 and fewest_moves=20 from public.mobile_enriched_game_records where mode='jigsaw'),'puzzle keeps independent minimums');
select pg_temp.reject_game($$select public.sync_enriched_game_records('[{"mode":"guess_choices","scope":"animals_all:hard","best_score":500,"best_time_ms":0,"fewest_moves":0,"played_at":1000,"updated_at":1000}]')$$,'check constraint');
select pg_temp.reject_game($$select public.sync_enriched_game_records('null')$$,'invalid_records');
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select pg_temp.check_game(public.get_enriched_game_records()='[]'::jsonb,'other account sees no progress');
select pg_temp.check_game((select count(*) from public.mobile_enriched_game_records)=0,'table RLS isolates accounts');
reset role;
select 'Enriched games: all SQL assertions passed' as result;
rollback;
